// Hard cap: refuse anything past iteration 5 so an Agent+auto-deploy
// loop can never run (and bill) unbounded.
const loop = parseInt(msg.req && msg.req.query && msg.req.query.loop, 10) || 1;
if (loop > 5) {
    msg.payload = 'Loop limit (5) reached - stopped.';
    return [msg, null];
}
const ack = RED.util.cloneMessage(msg);
ack.payload = 'Accepted iteration ' + loop + ' of 5.';
msg.loop = loop;
msg.payload = 'Self-feedback iteration ' + loop + ' of 5. Work ONLY in the flow "LLM feedback target".\n' +
    'Goal flow: an inject node that fires every 5 seconds -> a function node that picks a random integer 0-100 and sets msg.payload to "high: <n>" if n >= 50, else "low: <n>" -> a debug node.\n' +
    'If this demo flow does not exist yet, CREATE it. Otherwise review the current nodes and make ONE small concrete improvement to it (fix a bug, improve the function logic, clearer node names). Do not delete existing nodes, and do not add comment nodes.\n' +
    'If the flow already fulfils the goal and needs no further improvement, reply with exactly END - plain text only, no JSON block, and make no changes.';
return [ack, msg];

// Single source of the loop URL. The base comes from flow.apiBase,
// set once by the 'set API endpoint' change node at the top of this tab.
// msg.payload here is the LLM's text reply: when the LLM judges the demo
// flow complete it replies END (per the prompt) and the loop stops early.
const reply = (typeof msg.payload === 'string') ? msg.payload.trim() : '';
if (/^END\b/i.test(reply)) {
    msg.payload = 'LLM signalled END after iteration ' + (msg.loop || '?') + ' - loop finished.';
    return [null, msg];
}
const next = (msg.loop || 0) + 1;
if (next > 5) {
    msg.payload = 'Completed 5 iterations - loop finished.';
    return [null, msg];
}
const base = (flow.get('apiBase') || 'http://127.0.0.1:1880').replace(/\/+$/, '');
msg.url = base + '/llm-loop?loop=' + next;
msg.method = 'GET';
msg.payload = '';
return [msg, null];
